  [9024] = { nil, nil, nil, "Posso aiutarti in qualcosa?", nil, nil, nil, nil, 0xdf112bb5, nil, "mmm.m" },
  [9124] = { nil, nil, nil, "Come va la caccia?", nil, nil, nil, nil, 0xe02b27bb, nil, "mmm.m" },
  [9154] = { nil, "Consegna il Call to Arms Announcement al Keeper of the Rolls, alla Light's Hope Chapel nelle Eastern Plaguelands.", "Gli Scourge sono tornati più numerosi che mai. L'Argent Dawn arruola tutti gli uomini e le donne volenterosi e capaci per difendere le nostre terre.\n\nSe condividi la nostra causa, porta questo documento al Keeper of the Rolls, alla Light's Hope Chapel nelle Eastern Plaguelands.", "Sei qui per unirti al nostro ordine, vero?", "L'Argent Dawn ha lanciato la richiesta di aiuto, e tu, insieme ad altri, hai risposto. Non abbiamo tempo per addestrarti. Riponiamo la nostra fiducia nelle tue capacità, e nel fatto che ci aiuterai a respingere la minaccia degli Scourge.", nil, 0x3ddcc4ef, 0xf8db3513, 0xa0de5425, 0xb13b78e0, "m...." },
  [9260] = { nil, nil, nil, "Hai già indagato sull'invasione? Non c'è tempo da perdere!", "Mmm. Da quello che mi hai detto, le voci dentro i cerchi... devono servire a comunicare in qualche modo. Rabbrividisco al pensiero di quali menti innaturali vengano contattate con una magia simile. In ogni caso, sembri esserne <uscito/uscita> con il corpo e la mente intatti. L'Argent Dawn apprezza il tuo servizio.", nil, nil, nil, 0x5ea2db66, 0x4f3229e9, "mmm.." },
  [9261] = { nil, nil, nil, "Hai già indagato sull'invasione? Non c'è tempo da perdere!", "Mmm. Da quello che mi hai detto, le voci dentro i cerchi... devono servire a comunicare in qualche modo. Rabbrividisco al pensiero di quali menti innaturali vengano contattate con una magia simile. In ogni caso, sembri esserne <uscito/uscita> con il corpo e la mente intatti. L'Argent Dawn apprezza il tuo servizio.", nil, nil, nil, 0x5ea2db66, 0x4f3229e9, "mmm.." },
  [9262] = { "Indagare sugli Scourge di Darnassus", "Raccogli tre Dim Necrotic Stones dagli Scourge fuori Darnassus e indaga sui cerchi runici luminosi vicino al loro accampamento.", "Gli Scourge sono accampati proprio alla nostra porta; non possiamo restare con le mani in mano! Di sicuro ti farai avanti per difendere Darnassus da questi invasori maledetti?\n\nLà fuori ci sono strani cerchi runici, che brillano della stessa energia che circonda i non morti e la Necropolis lassù. Hanno un significato, ne sono certa, e voglio che tu scopra quale. Già che ci sei, sfoltisci quelle aberrazioni; portami la prova della loro morte insieme ai tuoi risultati e ti ricompenserò. Vai!", "Hai già indagato sull'invasione? Non c'è tempo da perdere!", "Mmm. Da quello che mi hai detto, le voci dentro i cerchi... devono servire a comunicare in qualche modo. Rabbrividisco al pensiero di quali menti innaturali vengano contattate con una magia simile. In ogni caso, sembri esserne <uscito/uscita> con il corpo e la mente intatti. L'Argent Dawn apprezza il tuo servizio.", 0xae0b4b57, 0x8c429383, 0x2683cc59, 0x5ea2db66, 0x4f3229e9, "....." },
  [9263] = { nil, nil, nil, "Hai già indagato sull'invasione? Non c'è tempo da perdere!", "Mmm. Da quello che mi hai detto, le voci dentro i cerchi... devono servire a comunicare in qualche modo. Rabbrividisco al pensiero di quali menti innaturali vengano contattate con una magia simile. In ogni caso, sembri esserne <uscito/uscita> con il corpo e la mente intatti. L'Argent Dawn apprezza il tuo servizio.", nil, nil, nil, 0x5ea2db66, 0x4f3229e9, "mmm.." },
  [9264] = { nil, nil, nil, "Hai già indagato sull'invasione? Non c'è tempo da perdere!", "Mmm. Da quello che mi hai detto, le voci dentro i cerchi... devono servire a comunicare in qualche modo. Rabbrividisco al pensiero di quali menti innaturali vengano contattate con una magia simile. In ogni caso, sembri esserne <uscito/uscita> con il corpo e la mente intatti. L'Argent Dawn apprezza il tuo servizio.", nil, nil, nil, 0x5ea2db66, 0x4f3229e9, "mmm.." },
  [9265] = { nil, nil, nil, "Hai già indagato sull'invasione? Non c'è tempo da perdere!", "Mmm. Da quello che mi hai detto, le voci dentro i cerchi... devono servire a comunicare in qualche modo. Rabbrividisco al pensiero di quali menti innaturali vengano contattate con una magia simile. In ogni caso, sembri esserne <uscito/uscita> con il corpo e la mente intatti. L'Argent Dawn apprezza il tuo servizio.", nil, nil, nil, 0x5ea2db66, 0x4f3229e9, "mmm.." },
  [9324] = { "Rubare la fiamma di Orgrimmar", "Riporta la Flame of Orgrimmar al Festival Loremaster.", "Questa fiamma, rubata dal cuore stesso di Orgrimmar, ti inonda di calore. Questo potere grezzo ti è estraneo, ma il Loremaster potrebbe saperne di più...", "Brilli praticamente di luce, {race}. Cos'hai lì?", "Cos'è questo? Se non sbaglio, questa fiamma è stata presa dal cuore stesso di Orgrimmar! I cuori feroci degli orchi e dei troll si riflettono nel suo calore bruciante. Che bell'aggiunta alla nostra collezione: che coraggio, intrufolarti nella tana del nemico per prendere la fiamma sacra!", 0x6060e294, 0x2c3b06e5, 0xa233ef98, 0x35bceb01, 0xb78afa9a, "....." },
  [9325] = { "Rubare la fiamma di Thunder Bluff", "Riporta la Flame of Thunder Bluff al Festival Loremaster.", "Questa fiamma, rubata agli sciamani di Thunder Bluff, ti inonda di calore. Questo potere grezzo ti è estraneo, ma il Loremaster potrebbe saperne di più...", "Brilli praticamente di luce, {race}. Cos'hai lì?", "Se non sbaglio, questo fuoco è stato preso dalle scogliere di Thunder Bluff! Come canta del potere degli spiriti! Sei <un/una> gran <ladro/ladra>, {name}. Prendi questo come giusto compenso per la tua abilità. Ora, se solo avessimo le fiamme di tutte e tre le città...", 0xd6d267fd, 0x4526bcd9, 0x4d8c9c93, 0x35bceb01, 0x94adecd4, "....." },
  [9326] = { "Rubare la fiamma dell'Undercity", "Riporta la Flame of the Undercity al Festival Loremaster.", "Questa fiamma, rubata dalle rovine sopra l'Undercity, ti inonda di calore. Questo potere grezzo ti è estraneo, ma il Loremaster potrebbe saperne di più...", "Brilli praticamente di luce, {race}. Cos'hai lì?", "Mmm... che fuoco strano! È smorzato, quasi cova sotto la cenere, ma il calore è intenso. E dici che l'hai preso all'Undercity? Affascinante. Con le fiamme di tutte e tre le città, chissà cosa potremmo fare?", 0x65e82239, 0x889a7f0a, 0xdcc8620d, 0x35bceb01, 0x7a708213, "....." },
  [9330] = { nil, nil, nil, "Brilli praticamente di luce, {race}. Cos'hai lì?", nil, nil, nil, nil, 0x35bceb01, nil, "mmm.m" },
  [9331] = { nil, nil, nil, "Brilli praticamente di luce, {race}. Cos'hai lì?", nil, nil, nil, nil, 0x35bceb01, nil, "mmm.m" },
  [9332] = { nil, nil, nil, "Brilli praticamente di luce, {race}. Cos'hai lì?", nil, nil, nil, nil, 0x35bceb01, nil, "mmm.m" },
  [9339] = { "La ricompensa di un ladro", "Riporta la Flame of Stormwind a (NAME).", "Questa fiamma, rubata dal cuore stesso di Stormwind, ti inonda di calore. Questo potere grezzo ti è estraneo, ma il (NAME) potrebbe saperne di più...", nil, "Oggi hai dato prova di te, {name}.\n\nNon ho molto altro da darti, ma ho questa corona: un dono adatto a un conquistatore. Che illumini il tuo cammino.", 0x6fd2503e, 0x9e249500, 0xc3ca99b1, nil, 0xe7fe3c18, "...m." },
  [9365] = { "La ricompensa di un ladro", nil, nil, nil, "Oggi hai dato prova di te, {name}.\n\nNon ho molto altro da darti, ma ho questa corona: un dono adatto a un conquistatore. Che illumini il tuo cammino.", 0x6fd2503e, nil, nil, nil, 0xe7fe3c18, ".mmm." },
  [9367] = { "La festa del fuoco", "Tocca i falò di Stormwind, Ironforge e Darnassus, poi parla con un Festival Loremaster nelle capitali.", "È di nuovo Midsummer!\n\nOgni anno, come vuole la tradizione, vengono scelti dei Flamekeepers che curino i falò nelle nostre capitali. Mentre i fuochi ardono in tutta Azeroth, è indispensabile che i nostri siano i più caldi e i più luminosi, per rendere il giusto omaggio alla stagione.\n\nAnzi, avrei un compito per te, se non ti dispiace. Non ho ancora saputo se i fuochi di tutte le capitali ardono come si deve. Vai di persona a scaldarti accanto ai fuochi: assicurati che siano caldi!", "I fuochi ardono?", "Eccellente! Sembra che quest'anno abbiamo nominato Flamekeepers diligenti, se i falò sono curati come dici. Grazie per averli ispezionati per me; tieni, prendi questo come piccolo segno della mia stima.", 0x5796d45d, 0x043f46cc, 0x3508e9e2, 0xf5f9a813, 0x7dc83d5c, "....." },
  [9368] = { "La festa del fuoco", nil, "È di nuovo Midsummer!\n\nOgni anno, come vuole la tradizione, vengono scelti dei Flamekeepers che curino i falò nelle nostre capitali. Mentre i fuochi ardono in tutta Azeroth, è indispensabile che i nostri siano i più caldi e i più luminosi, per rendere il giusto omaggio alla stagione.\n\nAnzi, avrei un compito per te, se non ti dispiace. Non ho ancora saputo se i fuochi di tutte le capitali ardono come si deve. Vai di persona a scaldarti accanto ai fuochi: assicurati che siano caldi!", nil, "Eccellente! Sembra che quest'anno abbiamo nominato Flamekeepers diligenti, se i falò sono curati come dici. Grazie per averli ispezionati per me; tieni, prendi questo come piccolo segno della mia stima.", 0x5796d45d, nil, 0x3508e9e2, nil, 0x7dc83d5c, ".m.m." },
  [9388] = { "Fiamme tremolanti a Kalimdor", "Visita i falò di Ashenvale, dei Barrens, di Darkshore e delle Stonetalon Mountains, poi parla con il Festival Flamekeeper.", "Oggi nel mondo ardono molte fiamme, {name}. I fuochi più difficili da curare sono quelli che bruciano verdi: senza sorveglianza non restano accesi a lungo. Assicurati che i fuochi smeraldo ardano ancora a Kalimdor per il nostro Flamekeeper, eh?\n\nLi troverai vicino a Ratchet nei Barrens, vicino al Master's Glaive a Darkshore, nella foresta di Ashenvale accanto al ponte vicino al Silverwing Outpost, e vicino alla strada per Windshear Crag lungo la strada principale delle Stonetalon Mountains.", "I fuochi non possono spegnersi finché la festa non è finita!", "Ahhh, dunque ardono ancora. Ne sono felice; non sarebbe giusto che quei fuochi si spegnessero prima del tempo. Hai fatto bene, {name}. Prendi questo con la mia benedizione.", 0x4231b5a1, 0xebc13200, 0x9fb3b754, 0x7346e6f0, 0x87796b40, "....." },
  [9389] = { "Fiamme tremolanti negli Eastern Kingdoms", "Visita i falò delle Hillsbrad Foothills, della Silverpine Forest, di Westfall e delle Wetlands, poi parla con il Festival Flamekeeper.", "Per tradizione, il Midsummer Fire Festival illumina la terra con una miriade di fiamme. Alcuni sostengono che i fuochi verdi siano i più belli, perché sono i più difficili da mantenere e hanno un colore così particolare.\n\nAssicurati che ardano ancora negli Eastern Kingdoms per il nostro Flamekeeper. Si trovano vicino a Dun Modr nelle Wetlands, vicino a Pyrewood Village nella Silverpine Forest, sulle scogliere che dominano il faro di Westfall e accanto alla torre in rovina nelle Hillsbrad Foothills.", "Hai svolto il tuo compito?", "Così sei <tornato/tornata>, e hai controllato le fiamme smeraldo del continente. Che ne pensi, eh? Uno spettacolo raro e meraviglioso, di sicuro. So però che le ricompense tangibili sono più apprezzate... quindi, ti prego, prendi questo per il disturbo.", 0x97c31d69, 0x8c77ebbe, 0x389c2696, 0x6640bff5, 0xe62c73ec, "....." },
})
